import os, re, json
from collections import defaultdict

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()

# Analyze both demos together
for name, grid in [('Demo 1 In', G['Demo pair 1 input']), 
                   ('Demo 1 Out', G['Demo pair 1 output']),
                   ('Demo 2 In', G['Demo pair 2 input']),
                   ('Demo 2 Out', G['Demo pair 2 output'])]:
    print(f"\n=== {name}: shape {len(grid)}x{len(grid[0])} ===")
    vals = set(val for row in grid for val in row)
    print(f"Values present: {sorted(vals)}")

# Find non-background values in each grid
def get_special_values(grid, common_bg_vals=None):
    # Background is usually one value dominating rows/cols
    # Special values are sparse ones
    vals_in_grid = defaultdict(int)
    for row in grid:
        for val in row:
            vals_in_grid[val] += 1

    return sorted(vals_in_grid.keys())

print("\n=== Count of each value ===")
for name in ['Demo 1 In', 'Demo 1 Out', 'Demo 2 In', 'Demo 2 Out']:
    grid = G[name.replace(' ', '_')]
    vals_count = defaultdict(int)
    for row in grid:
        for val in row:
            vals_count[val] += 1
    print(f"{name}: {dict(sorted(vals_count.items()))}")

